import{_ as e,o,c as a,a5 as s}from"./chunks/framework.DGp912Ge.js";const g=JSON.parse('{"title":"1. Specifications Check","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"guides/add-on/specifications.md","filePath":"guides/add-on/specifications.md","lastUpdated":1779437493000}'),n={name:"guides/add-on/specifications.md"};function i(r,t,d,l,c,h){return o(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="_1-specifications-check" tabindex="-1">1. Specifications Check <a class="header-anchor" href="#_1-specifications-check" aria-label="Permalink to &quot;1. Specifications Check&quot;">​</a></h1><p><strong>Goal:</strong> Verify your add-on (camera, LiDAR, computer, sensor, etc.) is within the robot&#39;s mechanical and electrical limits <strong>before</strong> attaching it.</p><p><strong>Prerequisites:</strong> None. Run this check first whenever you plan to install a new module.</p><h2 id="key-limits-for-rbq-10" tabindex="-1">Key Limits for RBQ 10 <a class="header-anchor" href="#key-limits-for-rbq-10" aria-label="Permalink to &quot;Key Limits for RBQ 10&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Limit</th><th>Why it matters</th></tr></thead><tbody><tr><td><strong>Max Payload</strong></td><td><strong>15 kg</strong></td><td>Total mass of everything mounted on top of the robot</td></tr><tr><td><strong>Mounting interface</strong></td><td><strong>Top rail (slot)</strong> + spring nuts</td><td>Use rail slots for repeatable, secure mounting</td></tr><tr><td><strong>Power available</strong></td><td><strong>54 V</strong>, <strong>12 V</strong></td><td>Check your add-on&#39;s input voltage / current draw</td></tr><tr><td><strong>Data interfaces</strong></td><td><strong>CAN ×1</strong>, <strong>Gigabit LAN ×3</strong></td><td>Match your add-on&#39;s communication interface</td></tr><tr><td><strong>Ingress Protection</strong></td><td><strong>IP54</strong></td><td>Add-ons should not compromise IP rating in field use</td></tr></tbody></table><p>For the full specification table (dimensions, walking speed, slope, sensors, etc.), see the manual page below.</p><p><strong><a href="/RBQ/manual/product-descriptions/general-specification.html">→ Full Specifications (manual)</a></strong></p><h2 id="pre-installation-checklist" tabindex="-1">Pre-installation Checklist <a class="header-anchor" href="#pre-installation-checklist" aria-label="Permalink to &quot;Pre-installation Checklist&quot;">​</a></h2><p>Before moving to the next step, confirm:</p><ul><li>[ ] Add-on mass + any existing payload <strong>≤ 15 kg</strong></li><li>[ ] Center of mass is <strong>roughly above the robot body</strong> (avoid large overhang)</li><li>[ ] Power and data interfaces match what RBQ 10 provides</li><li>[ ] You have <strong>measured the X / Y / Z offset</strong> of the add-on&#39;s center of mass from the robot body center (needed in step 3)</li></ul><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>Exceeding the <strong>15 kg</strong> payload limit or mounting mass far from the body center can destabilize walking, increase joint load, and shorten component life. Always check the spec sheet first.</p></div></div><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>When your add-on passes the checklist, mount it to the rail:</p><p><strong><a href="/RBQ/guides/add-on/rail-spring-nut.html">→ 2. Rail &amp; Spring Nut</a></strong></p>',14)])])}const u=e(n,[["render",i]]);export{g as __pageData,u as default};
